begin;
insert into public.campaign_briefs (campaign_id, starts_on, ends_on, headline, the_read, moves, watch, written_by)
select id, date '2026-10-21', date '2026-11-03', $h$Win the farm gate and the young before DCP settles on one man$h$, $j$[{"title": "DCP is the weather on the mountain, not a rival party", "stance": "threat", "body": "In June, Infotrak had Gachagua's DCP at 33% in Central and Mt Kenya against UDA's 9%. In July, DCP took Ol Kalou by 35,440 votes to 5,450 on 57% turnout. MPs who cross from UDA to DCP are being heckled in front of Gachagua himself, so leaving UDA does not buy acceptance. In Kiambu, anyone not on DCP's ticket is swimming against the regional current.\nThe current is about Gachagua, not his local candidates. Fight his candidates; never fight him.", "sources": [{"label": "People Daily: Infotrak, DCP most popular party in Mt Kenya", "url": "https://peopledaily.digital/inside-politics/infotrak-gachaguas-dcp-is-the-most-popular-party-in-mt-kenya", "date": null}, {"label": "IEBC: Ol Kalou by-election result", "url": "https://x.com/IEBCKenya/status/2077965009250828683", "date": "2026-07-16"}, {"label": "The Star: UDA defectors face uphill battle in Mt Kenya", "url": "https://www.the-star.co.ke/news/2026-10-15-uda-defectors-face-uphill-battle-for-acceptance-in-mt-kenya", "date": "2026-10-15"}, {"label": "Kenyans.co.ke: Kagombe heckled in front of Gachagua", "url": "https://www.kenyans.co.ke/news/126233-gatundu-south-mp-kagombe-heckled-hostile-crowd-front-gachagua", "date": null}]}, {"title": "Her opening: DCP's Githunguri ticket is a three-way fight", "stance": "opening", "body": "Gabriel Kago (MP 2017–22, 31,127 votes in 2022) joined DCP on 30 July to run here. In March, Gachagua stood at a Githunguri rally for lawyer Njenga Mabati and called him the grassroots candidate. Both want the same ticket. Nation reports aspirants accusing DCP of reserving seats for favourites, and DCP's primaries are already threatening to split the party. Whoever loses in Githunguri walks away with a network and a grievance.\nAn unpublished-method poll from February (Politrack, via Daily Express) had Charles Thiong'o 30%, Kago 26.8% and the MP trailing. Treat it as a warning, not a measurement.", "sources": [{"label": "Kahawatungu: Kago wa Lydia joins DCP", "url": "https://kahawatungu.com/former-githunguri-mp-kago-wa-lydia-joins-dcp-set-to-challenge-wamuchomba/", "date": "2026-07-30"}, {"label": "Kiambu Observer: Gachagua rallies Githunguri", "url": "https://kiambuobserver.co.ke/gachagua-rallies-githunguri-signals-political-offensive-ahead-of-2027", "date": null}, {"label": "Nation: Gachagua's picks test DCP's fair nominations promise", "url": "https://nation.africa/kenya/news/politics/why-gachagua-s-picks-test-dcp-s-promise-of-fair-nominations--5533268", "date": null}, {"label": "Nation: DCP primaries threaten to split the party", "url": "https://nation.africa/kenya/news/politics/gachagua-puts-coalition-talks-on-hold-as-dcp-primaries-threaten-to-split-party-5630854", "date": null}, {"label": "Daily Express: Githunguri poll (Politrack, method unpublished)", "url": "https://dailyexpress.co.ke/githunguri-mp-opinion-poll-2026/", "date": null}]}, {"title": "Her story why she left is the region's story", "stance": "strength", "body": "On 8 October she left UDA over \"selective justice\". She asked why Health CS Duale was not summoned over remarks reported as targeting the community, while Mukurweini's MP was arrested. That is the grievance DCP was built on, and she now owns it without owing Gachagua anything.\nTell it as equal treatment for every Kenyan, never as one community against another. That is what keeps it strong and lawful.", "sources": [{"label": "Citizen Digital: Wamuchomba exits UDA over Duale", "url": "https://citizen.digital/article/wamuchomba-announces-exit-from-uda-over-disrespect-by-cs-duale-n391659", "date": "2026-10-08"}, {"label": "Kenyans.co.ke: Wamuchomba announces exit from UDA", "url": "https://www.kenyans.co.ke/news/127703-mp-gathoni-wamuchomba-announces-exit-uda", "date": "2026-10-08"}]}, {"title": "The housing project is the attack DCP will run", "stance": "threat", "body": "In April she backed the affordable housing project on the 58-acre shrine land. Elders broke calabashes to curse it, police teargassed them, and a court order paused building until July. Gachagua has since said she and Ruto 'joined hands to grab the land'. It contradicts her best credential: she voted NO on the Finance Bill 2024 and called the housing programme the 'biggest scam' in 2023.\nShe can't run from it; she has to reframe it. The levy: no. Houses built here, for people from here, on terms the elders can see: yes.", "sources": [{"label": "Citizen Digital: Wamuchomba dares elders' curse", "url": "https://www.citizen.digital/article/wamuchomba-dares-kikuyu-elders-curse-vows-affordable-housing-project-wont-stop-n380562", "date": null}, {"label": "The Standard: teargas as elders curse housing project", "url": "https://www.standardmedia.co.ke/central/article/2001545068/police-lobe-teargas-as-elders-curse-reject-affordable-housing-in-githunguri", "date": null}, {"label": "KBC: how MPs voted on the Finance Bill 2024", "url": "https://www.kbc.co.ke/how-mps-voted-for-the-finance-bill-2024/", "date": null}, {"label": "The Star: Wamuchomba and Ichung'wah clash over the housing levy", "url": "https://www.the-star.co.ke/news/realtime/2024-02-21-mps-wamuchomba-ichungwah-clash-over-housing-levy", "date": "2024-02-21"}]}, {"title": "The farm gate decides Githunguri", "stance": "context", "body": "Githunguri Dairy turned over KES 11.4bn in FY2026 on 97 million litres. Its plant runs at about 60% of capacity, and feed, disease and drought are the threats it names. In 2024 farmers were stuck with 4 million unsold litres and blamed imports. KTDA's September pay and bonuses landed from 12 October at KSh12.50–50 a kilo, depending on the factory.\nIn 2022 Ruto carried the constituency easily while she beat Kago by only 3,519 votes (34,646 to 31,127): party loyalty bends here, farm income doesn't.", "sources": [{"label": "DairyBusiness MEA: Githunguri Dairy FY2026", "url": "https://dairybusinessmea.com/2026/10/12/githunguri-dairy-reports-us88-4m-in-fy-2026/", "date": "2026-10-12"}, {"label": "The Star: Githunguri farmers stuck with 4m litres", "url": "https://www.the-star.co.ke/counties/central/2024-11-04-githunguri-farmers-stuck-with-4m-litres-of-milk-blame-imports", "date": "2024-11-04"}, {"label": "The Star: tea pay and bonuses from Monday", "url": "https://www.the-star.co.ke/news/2026-10-09-tea-farmers-to-access-september-pay-and-bonuses-from-monday", "date": "2026-10-09"}, {"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}, {"label": "Team research: Kenya Electoral Strategy Research", "url": null, "date": null}]}, {"title": "First-time voters are the swing nobody here has organised", "stance": "opening", "body": "Kiambu added 97,557 new voters by 24 April, the second most after Nairobi; nationally IEBC added 2.6 million. In a PARS poll of 18–29 year-olds, 95% say they will vote, 6 in 10 feel unheard, and jobs and corruption are their top concerns. Kiambu had the most deaths at Saba Saba 2025 (8 of 38).\nHer Finance Bill NO is the only credential in this race that young voters already know. Use it before DCP's candidates claim the anger.", "sources": [{"label": "Nation: IEBC 1.8m new voters, Nairobi leads, Kiambu 97,557", "url": "https://nation.africa/kenya/news/iebc-hits-75pc-of-mass-listing-targets-with-1-8m-new-voters-5435836", "date": "2026-04-25"}, {"label": "IEBC: 2,612,725 new voters in 2026", "url": "https://www.iebc.or.ke/uploads/resources/axHuo7uUCM.pdf", "date": null}, {"label": "PARS Gen Z poll report", "url": "https://pars.co.ke/wp-content/uploads/2026/06/Gen-Z-Poll-Report-FINAL-23rd-June-2026.pdf", "date": "2026-06-23"}, {"label": "Citizen Digital: Saba Saba toll rises to 38 (KNCHR)", "url": "https://citizen.digital/article/death-toll-from-saba-saba-protests-rises-to-38-knchr-n366153", "date": null}, {"label": "KBC: how MPs voted on the Finance Bill 2024", "url": "https://www.kbc.co.ke/how-mps-voted-for-the-finance-bill-2024/", "date": null}]}, {"title": "The vehicle: decide now, announce at the end of the fortnight", "stance": "context", "body": "She has said she will consult voters and then name a party; about 7 months remain before primaries. Each route has a cost:\n- DCP: the biggest wave, but she vowed never to join, and its primary is already crowded.\n- PPK: Manyora argues it would not save the seat.\n- A smaller opposition-leaning party, or independent: keeps her out of DCP's primary and lets her collect its loser.\nOur read is the third route, with a public non-aggression line toward Gachagua. Turn the consultation itself into the campaign.", "sources": [{"label": "People Daily: four paths for Wamuchomba", "url": "https://peopledaily.digital/inside-politics/four-political-paths-wamuchomba-could-explore-after-ditching-rutos-uda", "date": null}, {"label": "People Daily: Manyora on Wamuchomba and PPK", "url": "https://peopledaily.digital/inside-politics/manyora-wamuchomba-cannot-be-re-elected-even-in-ndindi-nyoros-party", "date": null}, {"label": "Kenyans.co.ke: DCP nomination fees", "url": "https://www.kenyans.co.ke/news/126713-dcp-releases-2027-nomination-fees-mca-mp-governor-aspirants", "date": "2026-09-02"}]}]$j$::jsonb, $j$[{"from": 1, "to": 1, "title": "Kikuyu-language radio: why I left, in one sentence", "diary": {"kind": "media", "title": "Inooro / Kameme interview"}, "why": "Set the frame before rivals do: respect and equal justice, a party left, not people.", "how": ["One line: 'I left a party that treats our people unequally. I did not leave you.'", "Name the Finance Bill NO and the dairy as her two proofs.", "Announce the five-ward consultation and its dates on air."], "where": ["Githunguri"], "measure": "Clips shared; inbound SMS sign-ups the day after.", "sources": [{"label": "Citizen Digital: Wamuchomba exits UDA over Duale", "url": "https://citizen.digital/article/wamuchomba-announces-exit-from-uda-over-disrespect-by-cs-duale-n391659", "date": "2026-10-08"}]}, {"from": 2, "to": 6, "title": "Five-ward consultation barazas: 'Which vehicle?'", "diary": {"kind": "meeting", "title": "Consultation baraza"}, "why": "She promised to consult before choosing. Doing it in public turns her party decision into voters' decision, and gives her a list of names.", "how": ["One baraza per ward: Githunguri, Githiga, Komothai, Ikinu, Ngewa.", "Ask three questions on cards: which party, top worry, can we text you (consent recorded)?", "Invite the church, the dairy collection-centre chairs and the boda stage chairs to sit on the panel."], "where": ["Githunguri", "Githiga", "Komothai", "Ikinu", "Ngewa"], "measure": "300 consented sign-ups per baraza; 1,500 by Day 6.", "sources": [{"label": "People Daily: four paths for Wamuchomba", "url": "https://peopledaily.digital/inside-politics/four-political-paths-wamuchomba-could-explore-after-ditching-rutos-uda", "date": null}]}, {"from": 3, "to": 7, "title": "Dawn at the collection centres: the milk price plan", "diary": {"kind": "visit", "title": "Dairy collection centres at dawn"}, "why": "The farm gate decides this seat. Bonus season is now, and so is the import grievance.", "how": ["Be at 4 collection centres between 6 and 8am, in Komothai, Ikinu and Githiga first.", "Pledge three things: fight cheap milk imports, a feed-cost plan, and co-op transparency.", "Meet KTDA factory directors on the bonus and on factory governance."], "where": ["Komothai", "Ikinu", "Githiga"], "measure": "Farmers signed up; a co-op chair on record backing the plan.", "sources": [{"label": "DairyBusiness MEA: Githunguri Dairy FY2026", "url": "https://dairybusinessmea.com/2026/10/12/githunguri-dairy-reports-us88-4m-in-fy-2026/", "date": "2026-10-12"}, {"label": "The Star: Githunguri farmers stuck with 4m litres", "url": "https://www.the-star.co.ke/counties/central/2024-11-04-githunguri-farmers-stuck-with-4m-litres-of-milk-blame-imports", "date": "2024-11-04"}, {"label": "The Star: tea pay and bonuses from Monday", "url": "https://www.the-star.co.ke/news/2026-10-09-tea-farmers-to-access-september-pay-and-bonuses-from-monday", "date": "2026-10-09"}]}, {"from": 4, "to": 8, "title": "Take the housing attack off the table", "diary": {"kind": "meeting", "title": "Elders and the housing project"}, "why": "DCP will run 'land grab' all year. Meet the elders before DCP does, and publish the terms.", "how": ["A closed meeting with the elders who cursed the project: listen first.", "Publish one page: the court position, how many units, what share goes to local families, how many local jobs.", "Separate the levy (she opposed it) from houses here (on local terms)."], "where": ["Githunguri"], "measure": "No new elder statement against her; the one-pager shared in all five wards.", "sources": [{"label": "Citizen Digital: Wamuchomba dares elders' curse", "url": "https://www.citizen.digital/article/wamuchomba-dares-kikuyu-elders-curse-vows-affordable-housing-project-wont-stop-n380562", "date": null}, {"label": "The Standard: teargas as elders curse housing project", "url": "https://www.standardmedia.co.ke/central/article/2001545068/police-lobe-teargas-as-elders-curse-reject-affordable-housing-in-githunguri", "date": null}, {"label": "The Star: Wamuchomba and Ichung'wah clash over the housing levy", "url": "https://www.the-star.co.ke/news/realtime/2024-02-21-mps-wamuchomba-ichungwah-clash-over-housing-levy", "date": "2024-02-21"}]}, {"from": 5, "to": 10, "title": "Gen Z: a jobs town hall at the TVET college", "diary": {"kind": "meeting", "title": "Youth jobs town hall"}, "why": "First-time voters are the swing nobody has organised, and her Finance Bill NO is the credential they know.", "how": ["Hold it at Githunguri TVC (the new hostels are her proof of delivery).", "Topic: jobs in the dairy value chain (transport, feed, processing) and digital work.", "Recruit 50 youth volunteers to run TikTok and WhatsApp for the campaign."], "where": ["Githunguri"], "measure": "Volunteers recruited; first-time voters signed up.", "sources": [{"label": "PARS Gen Z poll report", "url": "https://pars.co.ke/wp-content/uploads/2026/06/Gen-Z-Poll-Report-FINAL-23rd-June-2026.pdf", "date": "2026-06-23"}, {"label": "Nation: IEBC 1.8m new voters, Nairobi leads, Kiambu 97,557", "url": "https://nation.africa/kenya/news/iebc-hits-75pc-of-mass-listing-targets-with-1-8m-new-voters-5435836", "date": "2026-04-25"}, {"label": "KBC: how MPs voted on the Finance Bill 2024", "url": "https://www.kbc.co.ke/how-mps-voted-for-the-finance-bill-2024/", "date": null}]}, {"from": 6, "to": 12, "title": "Walk the rural wards with one message", "diary": null, "why": "Persuasion beats mobilisation here: turnout is already high, and in 2022 she won by 3,519.", "how": ["Komothai and Ikinu first, then Ngewa: the walk lists are in the field plan.", "At the door: one issue (the milk price), one proof (the Finance Bill NO), one ask (consent to text).", "Mark support 1–5 so the next round goes to the 3s."], "where": ["Komothai", "Ikinu", "Ngewa"], "measure": "Doors knocked against the field plan; share of conversations at 4–5.", "sources": [{"label": "Team research: Kenya Electoral Strategy Research", "url": null, "date": null}, {"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}]}, {"from": 8, "to": 11, "title": "Open the door to DCP's losing camp, quietly", "diary": null, "why": "Kago and Mabati can't both win DCP's ticket. Whoever loses brings a network and a grievance.", "how": ["Map each camp's ward chairs, church and chama links.", "Meet any aspirant's people one-to-one, never in public, with no attacks on either man.", "Have a standing offer ready: a role in the campaign and a ward project."], "where": ["Githunguri"], "measure": "Named contacts in each camp.", "sources": [{"label": "Kahawatungu: Kago wa Lydia joins DCP", "url": "https://kahawatungu.com/former-githunguri-mp-kago-wa-lydia-joins-dcp-set-to-challenge-wamuchomba/", "date": "2026-07-30"}, {"label": "Kiambu Observer: Gachagua rallies Githunguri", "url": "https://kiambuobserver.co.ke/gachagua-rallies-githunguri-signals-political-offensive-ahead-of-2027", "date": null}, {"label": "Nation: DCP primaries threaten to split the party", "url": "https://nation.africa/kenya/news/politics/gachagua-puts-coalition-talks-on-hold-as-dcp-primaries-threaten-to-split-party-5630854", "date": null}]}, {"from": 14, "to": 14, "title": "Announce the vehicle in Githunguri town", "diary": {"kind": "rally", "title": "The people's choice: announcing the vehicle"}, "why": "Close the consultation in public, with the sign-ups behind her: the decision belongs to the five wards.", "how": ["Read out the consultation results ward by ward.", "Name the party and the three pledges: milk, youth jobs, equal justice.", "Hold the line on Gachagua: no attacks, only on his local candidates' records."], "where": ["Githunguri"], "measure": "Crowd size, sign-ups and press coverage the next day.", "sources": [{"label": "People Daily: four paths for Wamuchomba", "url": "https://peopledaily.digital/inside-politics/four-political-paths-wamuchomba-could-explore-after-ditching-rutos-uda", "date": null}]}]$j$::jsonb, $j$[{"title": "DCP's Githunguri nomination", "body": "Whether Kago or Mabati gets the ticket, and whether the loser walks.", "sources": [{"label": "Nation: Gachagua's picks test DCP's fair nominations promise", "url": "https://nation.africa/kenya/news/politics/why-gachagua-s-picks-test-dcp-s-promise-of-fair-nominations--5533268", "date": null}, {"label": "Nation: DCP primaries threaten to split the party", "url": "https://nation.africa/kenya/news/politics/gachagua-puts-coalition-talks-on-hold-as-dcp-primaries-threaten-to-split-party-5630854", "date": null}]}, {"title": "Wamatangi's party in December", "body": "Kiambu's governor ruled out UDA and says he will name his party in December. His choice reshapes every Kiambu ticket.", "sources": [{"label": "Nation: Wamatangi mulls ditching UDA", "url": "https://nation.africa/kenya/news/politics/wamatangi-mulls-ditching-uda-after-fallout-5553986", "date": null}]}, {"title": "Gachagua's eligibility appeal", "body": "The High Court upheld his impeachment in June. If the appeal fails he becomes a pure kingmaker; TIFA already says his best route is backing someone else.", "sources": [{"label": "Kenyans.co.ke: why Gachagua can still run despite the ruling", "url": "https://www.kenyans.co.ke/news/124119-explained-why-gachagua-can-still-run-president-despite-court-ruling", "date": null}, {"label": "Citizen Digital: TIFA, Gachagua's best chance is backing another", "url": "https://citizen.digital/article/gachaguas-best-chance-of-beating-ruto-in-2027-is-backing-opposition-candidate-tifa-n387035", "date": null}]}, {"title": "Political violence", "body": "She reported her car stoned at a road launch in June 2025. Plan security for every rally and log every incident.", "sources": [{"label": "People Daily: Wamuchomba raises alarm over political violence", "url": "https://peopledaily.digital/inside-politics/wamuchomba-raises-alarm-over-political-violence-in-githunguri-blames-ex-mp-gabriel-kago", "date": null}]}]$j$::jsonb, 'Groundwork'
from public.campaigns where slug = 'githunguri';
insert into public.campaign_briefs (campaign_id, starts_on, ends_on, headline, the_read, moves, watch, written_by)
select id, date '2026-10-21', date '2026-11-03', $h$Be the one Ruto can't beat, and make the opposition admit it before Sifuna's wave does$h$, $j$[{"title": "The only head-to-head Ruto loses is against Kalonzo", "stance": "strength", "body": "In Mizani's September head-to-heads, Ruto beats Gachagua 54.0–33.9, Matiang'i 53.3–41.0 and Sifuna 50.1–45.8. Kalonzo beats Ruto 51.3–47.7. In August, the Swiss Poll found 41% of anti-Ruto voters preferred Kalonzo as the opposition's candidate. 'Electability' is his whole argument, and he should make it in numbers, every day.", "sources": [{"label": "allAfrica: Mizani, Kalonzo beats Ruto head to head", "url": "https://allafrica.com/stories/202609250408.html", "date": "2026-09-25"}, {"label": "Capital FM: Mizani presidential survey", "url": "https://capitalfm.africa/mizani-poll-ruto-leads-kalonzo-sifuna-in-presidential-preference-survey/", "date": null}, {"label": "Capital FM: Swiss Poll, Kalonzo leads opposition choice", "url": "https://capitalfm.africa/kalonzo-emerges-as-leading-opposition-choice-in-2027-race-swiss-poll-shows/", "date": "2026-08-20"}]}, {"title": "Sifuna is rising faster than anyone", "stance": "threat", "body": "Raila Odinga died on 15 October 2025. ODM's leadership under Oburu Oginga will back Ruto, but its voters are going the other way: TIFA has 44% of ODM supporters choosing Sifuna against 20% for Ruto. Sifuna went from 10% to 15% between May and June, passing Kalonzo for the first time, and reached 19.6% in Politrack's September text-message poll. Linda Mwananchi endorsed him as its candidate on 26 September.\nOver the same months Kalonzo slid in TIFA, from 25% in November to 13% in June.", "sources": [{"label": "TIME: Raila Odinga's death and Kenya's future", "url": "https://time.com/7327473/odinga-death-kenya-uncertain-future/", "date": "2025-10-15"}, {"label": "The Star: ODM to back Ruto, fight all other seats", "url": "https://the-star.co.ke/news/2026-10-18-odm-to-back-ruto-fight-for-all-other-seats", "date": "2026-10-18"}, {"label": "The Star: TIFA, most ODM supporters back Sifuna", "url": "https://www.the-star.co.ke/news/2026-07-24-tifa-most-odm-supporters-back-sifuna-as-presidential-flagbearer", "date": "2026-07-24"}, {"label": "The Star: TIFA, Sifuna up, Gachagua and Kalonzo down", "url": "https://www.the-star.co.ke/news/2026-07-24-tifa-sifuna-popularity-surges-as-gachagua-kalonzo-drop", "date": "2026-07-24"}, {"label": "Nation: Politrack, Sifuna surges", "url": "https://nation.africa/kenya/news/politics/survey-ruto-commands-lead-sifuna-surges-5618820", "date": null}, {"label": "Eastleigh Voice: Linda Mwananchi endorses Sifuna", "url": "https://eastleighvoice.co.ke/politics/405258/linda-mwananchi-endorses-sifuna-as-2027-presidential-candidate", "date": null}]}, {"title": "No flagbearer yet, and the clock favours the momentum candidate", "stance": "threat", "body": "Kalonzo promised a choice by the first quarter of 2026 and the opposition missed it. His camp wants the principals to negotiate; the Gachagua and Matiang'i camps want polls to decide. Uhuru re-endorsed Matiang'i on 22 September, and Gachagua says one candidate will be named.\nEvery month without a decision is a month for Sifuna's surge to become the default.", "sources": [{"label": "People Daily: inside the opposition's endless talks", "url": "https://peopledaily.digital/inside-politics/inside-oppositions-endless-talks-as-leaders-wrestle-over-rutos-2027-challenger", "date": null}, {"label": "Kenyan Post: Gachagua predicts one opposition candidate", "url": "https://www.kenyan-post.com/2026/09/gachagua-predicts-senior-opposition.html", "date": null}, {"label": "allAfrica: Uhuru re-endorses Matiang'i", "url": "https://allafrica.com/stories/202609220173.html", "date": "2026-09-22"}]}, {"title": "The map: a bloc at home, a split mountain, and Western in play", "stance": "context", "body": "As polls and the press report the regions:\n- Ukambani: Infotrak in June had Kalonzo at 40% to Ruto's 19%. Not every Ukambani party will fold into Wiper.\n- Mt Kenya: DCP leads Central, but Ruto is pushing an East–West split through Kindiki (Ruto 54% in Mt Kenya North, 12% in Central).\n- Western: a 3.2-million-vote basket where Mudavadi and Wetang'ula hold for Ruto while Natembeya and Sifuna pull the other way.\n- Nyanza: its leaders now sit with Ruto through ODM, while its voters lean ODM and Sifuna.\nA winning opposition ticket has to unite Ukambani and Mt Kenya and take a real share of Western and Nyanza.", "sources": [{"label": "Kenyans.co.ke: Infotrak, Kalonzo second, leads Ukambani", "url": "https://www.kenyans.co.ke/news/125200-ruto-maintains-lead-among-presidential-aspirants-2027-race-kalonzo-2nd-infotrak-poll", "date": null}, {"label": "Citizen: Ukambani parties will not dissolve for Kalonzo", "url": "https://citizen.digital/article/muli-ukambani-parties-will-not-dissolve-to-support-kalonzo-n389958", "date": null}, {"label": "The Star: inside the Mt Kenya East–West divide", "url": "https://www.the-star.co.ke/news/2026-07-21-inside-the-mt-kenya-east-west-divide", "date": "2026-07-21"}, {"label": "Nation: Infotrak, Ruto leading", "url": "https://nation.africa/kenya/news/politics/poll-ruto-is-leading-presidential-hopeful--5525470", "date": null}, {"label": "Nation: the scramble for Western's 3.2m votes", "url": "https://nation.africa/kenya/news/politics/ruto-and-opposition-scramble-for-westerns-3-2m-vote-basket--5497762", "date": null}, {"label": "The Star: ODM to back Ruto, fight all other seats", "url": "https://the-star.co.ke/news/2026-10-18-odm-to-back-ruto-fight-for-all-other-seats", "date": "2026-10-18"}]}, {"title": "Ruto's open wounds", "stance": "opening", "body": "The Court of Appeal upheld the housing levy on 25 September. The Controller of Budget says SHA owes county hospitals at least Sh26.87bn, and providers that hadn't re-contracted were locked out from 1 October. Amnesty counts 19 disappearances and 69 police killings in 2026 so far. Ruto leads every poll but sits under 50% in all of them.", "sources": [{"label": "Bloomberg: appeals court upholds housing levy", "url": "https://www.bloomberg.com/news/articles/2026-09-25/kenyan-appeals-court-upholds-president-s-unpopular-housing-levy", "date": "2026-09-25"}, {"label": "Nation editorial: SHA debts", "url": "https://nation.africa/kenya/blogs-opinion/editorials/sha-debts-unhealthy-5514612", "date": null}, {"label": "Capital FM: Amnesty to Ruto on disappearances", "url": "https://capitalfm.africa/amnesty-to-ruto-turn-promises-on-enforced-disappearances-into-action/", "date": null}, {"label": "The Star: Politrack, Ruto tops at 45.1%", "url": "https://www.the-star.co.ke/news/2026-10-01-ruto-tops-presidential-race-poll-with-451", "date": "2026-10-01"}]}, {"title": "The Sifuna question is a deal to make, not a fight to have", "stance": "opening", "body": "Kalonzo has said he could back Sifuna but polls must not pick the ticket. The stronger play is the reverse offer: a Kalonzo–Sifuna ticket, with Kalonzo's electability and Sifuna's energy and the young ODM base. Gachagua's own TIFA numbers say his best move is backing another candidate. Make him a partner in this ticket, not a rival.", "sources": [{"label": "allAfrica: Kalonzo open to backing Sifuna", "url": "https://allafrica.com/stories/202608100357.html", "date": "2026-08-10"}, {"label": "Citizen Digital: TIFA, Gachagua's best chance is backing another", "url": "https://citizen.digital/article/gachaguas-best-chance-of-beating-ruto-in-2027-is-backing-opposition-candidate-tifa-n387035", "date": null}]}]$j$::jsonb, $j$[{"from": 1, "to": 2, "title": "Publish 'the head-to-head' and make it the message", "diary": {"kind": "media", "title": "Press briefing: the only candidate who beats Ruto"}, "why": "His one unanswerable argument is electability. Put it in front of the principals, the press and the voters.", "how": ["One chart: Mizani's head-to-heads, with the source on it.", "Offer: Kalonzo will accept any credible joint poll that also asks head-to-head questions.", "Answer the slide in TIFA: the head-to-head is what decides an election, preference polls are not."], "where": ["Nairobi"], "measure": "Coverage; whether principals respond to the joint-poll offer.", "sources": [{"label": "allAfrica: Mizani, Kalonzo beats Ruto head to head", "url": "https://allafrica.com/stories/202609250408.html", "date": "2026-09-25"}, {"label": "The Star: TIFA, Sifuna up, Gachagua and Kalonzo down", "url": "https://www.the-star.co.ke/news/2026-07-24-tifa-sifuna-popularity-surges-as-gachagua-kalonzo-drop", "date": "2026-07-24"}]}, {"from": 2, "to": 5, "title": "Open the Sifuna channel", "diary": {"kind": "meeting", "title": "Private meeting: Sifuna camp"}, "why": "Sifuna has the momentum and the ODM rank and file; Kalonzo has the head-to-head. A joint ticket beats a contest.", "how": ["Send an emissary to Linda Mwananchi with a ticket offer, privately and before any public statement.", "Agree on a shared line on Raila's legacy for the Nyanza and Western tours.", "No public criticism of Sifuna by any Wiper official."], "where": ["Nairobi"], "measure": "A second meeting is held.", "sources": [{"label": "Eastleigh Voice: Linda Mwananchi endorses Sifuna", "url": "https://eastleighvoice.co.ke/politics/405258/linda-mwananchi-endorses-sifuna-as-2027-presidential-candidate", "date": null}, {"label": "allAfrica: Kalonzo open to backing Sifuna", "url": "https://allafrica.com/stories/202608100357.html", "date": "2026-08-10"}, {"label": "The Star: TIFA, most ODM supporters back Sifuna", "url": "https://www.the-star.co.ke/news/2026-07-24-tifa-most-odm-supporters-back-sifuna-as-presidential-flagbearer", "date": "2026-07-24"}]}, {"from": 4, "to": 8, "title": "Western and Nyanza: the Raila legacy tour", "diary": {"kind": "rally", "title": "Western tour"}, "why": "These are the regions where ODM's leaders went one way and its voters another. Speak to the voters.", "how": ["Kakamega and Bungoma with Natembeya's allies; Kisumu and Siaya town halls.", "Message: the levy, SHA's arrears and police killings: Raila's fights, unfinished.", "Recruit polling-station agents as he goes."], "where": ["Kakamega", "Bungoma", "Kisumu", "Siaya"], "measure": "Agents recruited per county; local coverage.", "sources": [{"label": "Nation: the scramble for Western's 3.2m votes", "url": "https://nation.africa/kenya/news/politics/ruto-and-opposition-scramble-for-westerns-3-2m-vote-basket--5497762", "date": null}, {"label": "The Star: ODM to back Ruto, fight all other seats", "url": "https://the-star.co.ke/news/2026-10-18-odm-to-back-ruto-fight-for-all-other-seats", "date": "2026-10-18"}, {"label": "Nation editorial: SHA debts", "url": "https://nation.africa/kenya/blogs-opinion/editorials/sha-debts-unhealthy-5514612", "date": null}, {"label": "Capital FM: Amnesty to Ruto on disappearances", "url": "https://capitalfm.africa/amnesty-to-ruto-turn-promises-on-enforced-disappearances-into-action/", "date": null}]}, {"from": 6, "to": 10, "title": "Hold Ukambani: no party left outside the tent", "diary": {"kind": "meeting", "title": "Ukambani leaders' forum"}, "why": "A 40% home bloc is the base of everything. Smaller Ukambani parties refusing to fold are the leak.", "how": ["Offer the smaller parties seats in a coalition rather than a merger.", "Settle Kitui's governor contest by the agreed poll, quickly and visibly fair."], "where": ["Machakos", "Kitui", "Makueni"], "measure": "Smaller parties signed to the coalition.", "sources": [{"label": "Kenyans.co.ke: Infotrak, Kalonzo second, leads Ukambani", "url": "https://www.kenyans.co.ke/news/125200-ruto-maintains-lead-among-presidential-aspirants-2027-race-kalonzo-2nd-infotrak-poll", "date": null}, {"label": "Citizen: Ukambani parties will not dissolve for Kalonzo", "url": "https://citizen.digital/article/muli-ukambani-parties-will-not-dissolve-to-support-kalonzo-n389958", "date": null}]}, {"from": 9, "to": 12, "title": "Mt Kenya with Gachagua, on the record", "diary": {"kind": "rally", "title": "Mt Kenya joint rally"}, "why": "DCP leads Central, and Gachagua's own numbers say he should back someone else. Lock that in public.", "how": ["A joint rally in Kiambu or Murang'a.", "Ask Gachagua to say the words 'our candidate' on stage.", "Meet Mt Kenya East leaders separately, where Ruto is strongest through Kindiki."], "where": ["Kiambu", "Murang'a", "Meru"], "measure": "A public Gachagua statement of support.", "sources": [{"label": "People Daily: Infotrak, DCP most popular party in Mt Kenya", "url": "https://peopledaily.digital/inside-politics/infotrak-gachaguas-dcp-is-the-most-popular-party-in-mt-kenya", "date": null}, {"label": "Citizen Digital: TIFA, Gachagua's best chance is backing another", "url": "https://citizen.digital/article/gachaguas-best-chance-of-beating-ruto-in-2027-is-backing-opposition-candidate-tifa-n387035", "date": null}, {"label": "The Star: inside the Mt Kenya East–West divide", "url": "https://www.the-star.co.ke/news/2026-07-21-inside-the-mt-kenya-east-west-divide", "date": "2026-07-21"}]}, {"from": 11, "to": 14, "title": "Youth: one policy, one platform", "diary": {"kind": "media", "title": "Gen Z town hall (online)"}, "why": "95% of 18–29 year-olds say they will vote; jobs and corruption top their list. They are Sifuna's ground unless Kalonzo meets them.", "how": ["A live X or TikTok town hall, unscripted.", "One costed youth jobs pledge and an end to enforced disappearances, with a named mechanism."], "where": ["Online"], "measure": "Live viewers; volunteers signed up.", "sources": [{"label": "PARS Gen Z poll report", "url": "https://pars.co.ke/wp-content/uploads/2026/06/Gen-Z-Poll-Report-FINAL-23rd-June-2026.pdf", "date": "2026-06-23"}, {"label": "Capital FM: Amnesty to Ruto on disappearances", "url": "https://capitalfm.africa/amnesty-to-ruto-turn-promises-on-enforced-disappearances-into-action/", "date": null}]}]$j$::jsonb, $j$[{"title": "The flagbearer process", "body": "Whether the principals adopt polling or negotiation; Gachagua has promised one candidate.", "sources": [{"label": "Kenyan Post: Gachagua predicts one opposition candidate", "url": "https://www.kenyan-post.com/2026/09/gachagua-predicts-senior-opposition.html", "date": null}, {"label": "People Daily: inside the opposition's endless talks", "url": "https://peopledaily.digital/inside-politics/inside-oppositions-endless-talks-as-leaders-wrestle-over-rutos-2027-challenger", "date": null}]}, {"title": "Gachagua's appeal", "body": "His eligibility decides whether he is a candidate or a kingmaker.", "sources": [{"label": "Kenyans.co.ke: why Gachagua can still run despite the ruling", "url": "https://www.kenyans.co.ke/news/124119-explained-why-gachagua-can-still-run-president-despite-court-ruling", "date": null}]}, {"title": "ODM's split", "body": "Raila Jnr has joined a faction; watch Nyanza leaders who break from the Ruto line.", "sources": [{"label": "The Star: ODM to back Ruto, fight all other seats", "url": "https://the-star.co.ke/news/2026-10-18-odm-to-back-ruto-fight-for-all-other-seats", "date": "2026-10-18"}]}]$j$::jsonb, 'Groundwork'
from public.campaigns where slug = 'kalonzo';
insert into public.campaign_briefs (campaign_id, starts_on, ends_on, headline, the_read, moves, watch, written_by)
select id, date '2026-10-21', date '2026-11-03', $h$Settle the party, show the record street by street, and let a split field do the rest$h$, $j$[{"title": "He is behind, everywhere but one poll", "stance": "threat", "body": "CAP's July poll (4,500 people, face to face) had Babu Owino 36%, Kagure 32%, Sakaja 11%, Lucheri 10% and Gakuya 7%, with 84% disapproving of the governor. Kenya Track in March had Sakaja at 6%. Only Darubini in May (500 people) put him first, at 48%.\nOne caution: CAP's chief executive was Kagure's 2022 running mate. Still, the direction is clear.", "sources": [{"label": "Citizen Digital: CAP July poll, Babu leads, Kagure gains", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-still-leads-as-agnes-kagure-gains-traction-n387114", "date": "2026-07-25"}, {"label": "TV47: Kenya Track, Babu leads early race", "url": "https://www.tv47.digital/kenya-track-survey-babu-owino-leads-early-race-for-nairobi-governorship-as-2027-battle-takes-shape-142939/", "date": "2026-03-20"}, {"label": "The Star: Darubini, Sakaja 48%", "url": "https://www.the-star.co.ke/counties/nairobi/2026-05-22-sakaja-leads-nairobi-governor-race-with-48-support", "date": "2026-05-22"}, {"label": "Citizen Digital: CAP April poll", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-leads-agnes-kagure-follows-as-sakaja-trails-in-new-poll-n381233", "date": "2026-04-21"}]}, {"title": "Raila's shield is gone, and ODM's delegates said no", "stance": "threat", "body": "In September 2025, more than 70 of 123 MCAs signed to impeach him; Raila stopped it at JOOF and Ruto met UDA's MCAs. Raila died in October 2025. Sakaja told Inooro in August that ODM is the most popular party in Nairobi and that he was thinking about it. On 26 September, ODM's Nairobi delegates rejected him and backed George Aladwa, and ODM MPs insist he face primaries.", "sources": [{"label": "Kenyans.co.ke: MCAs drop impeachment after Raila meeting", "url": "https://www.kenyans.co.ke/news/115877-odm-mcas-drop-sakajas-impeachment-motion-after-raila-meeting", "date": "2025-09-02"}, {"label": "TIME: Raila Odinga's death and Kenya's future", "url": "https://time.com/7327473/odinga-death-kenya-uncertain-future/", "date": "2025-10-15"}, {"label": "Kenyans.co.ke: Sakaja hints at ODM move", "url": "https://www.kenyans.co.ke/news/126119-sakaja-hints-possible-odm-move-ahead-2027-nairobi-race", "date": "2026-08-12"}, {"label": "The Standard: ODM delegates reject Sakaja", "url": "https://www.standardmedia.co.ke/article/2001558772/odm-delegates-reject-sakaja-using-the-party-for-gubernatorial-bid", "date": "2026-09-26"}, {"label": "Kenyans.co.ke: ODM MPs tell Sakaja to face primaries", "url": "https://www.kenyans.co.ke/news/126838-odm-mps-tell-sakaja-face-party-primaries-2027-nairobi-governor-seat", "date": "2026-09-06"}]}, {"title": "A split field is his best friend", "stance": "opening", "body": "Governor is first past the post. The field is Babu (TMP, Linda Mwananchi), Kagure (KPP), Gakuya (DCP), Karauri, Mosiria (Jubilee, from Sakaja's own team), and Gachoka (KANU). On 18 October, Kagure's supporters threatened to back Sakaja if the opposition gives someone else a direct ticket. Gachagua claims DCP will take most of Nairobi's seats; CAP has DCP as the city's top party at 28%.\nThe more candidates on the ballot, the lower the winning number.", "sources": [{"label": "Citizen Digital: City Hall chessboard", "url": "https://citizen.digital/article/city-hall-chessboard-sakaja-babu-gakuya-karauri-gear-up-for-2027-nairobi-battle-n390883", "date": "2026-09-25"}, {"label": "Citizen Digital: Mosiria declares", "url": "https://citizen.digital/article/mr-fix-it-mosiria-declares-interest-to-run-for-nairobi-governors-seat-n391809", "date": "2026-10-11"}, {"label": "Kenyans.co.ke: Kagure supporters threaten to back Sakaja", "url": "https://www.kenyans.co.ke/news/127932-kagure-supporters-threaten-back-sakaja-over-unfair-opposition-nominations", "date": "2026-10-18"}, {"label": "The Standard: Gachagua vows DCP dominance in Nairobi", "url": "https://www.standardmedia.co.ke/politics/article/2001551837/gachagua-vows-dcp-dominance-in-nairobi-in-2027", "date": "2026-07-02"}, {"label": "Citizen Digital: CAP July poll, Babu leads, Kagure gains", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-still-leads-as-agnes-kagure-gains-traction-n387114", "date": "2026-07-25"}]}, {"title": "The record is real; it is just invisible", "stance": "strength", "body": "Dishi na County feeds about 316,000 learners in 230 schools from 17 kitchens. The Sh80bn State House pact covers lighting, nine informal settlements, Ng'ethu water, the river sewers and roads; he claims more than 160 km of 300 done, and the Ngong Road flyover is finished. He dropped the hawker ban for zones and hours. Voters can't see any of it as one story.", "sources": [{"label": "Citizen Digital: Dishi na County boosts attendance", "url": "https://citizen.digital/article/nairobis-dishi-na-county-programme-boosts-school-attendance-and-learning-n376454", "date": "2026-01-26"}, {"label": "The Star: Sh80bn Ruto–Sakaja pact", "url": "https://www.the-star.co.ke/news/2026-02-17-nairobi-set-for-sh80bn-upgrade-in-ruto-sakaja-pact", "date": "2026-02-17"}, {"label": "TV47: the pact five months on", "url": "https://www.tv47.digital/inside-the-ruto-sakaja-pact-five-months-after-the-ksh80-billion-deal-hit-or-miss-157127/", "date": "2026-07-25"}, {"label": "Kenyans.co.ke: Sakaja rules out banning hawking", "url": "https://www.kenyans.co.ke/news/126512-sakaja-rules-out-banning-street-hawking-explains-management-plan", "date": "2026-08-26"}]}, {"title": "Where 2022 was won, and who holds it now", "stance": "context", "body": "2022 was 699,392 to Igathe's 573,516. His strongholds were Roysambu (63,175 to 24,981), Kasarani (60,578 to 27,862), Dagoretti South and Starehe. Six seats were near-ties: Dagoretti North, Lang'ata, Westlands, Mathare, Makadara and Embakasi West.\nCAP's July poll now has Kagure ahead in his strongholds and Babu ahead in four of the near-ties. New voters lean young, and Nairobi led registration with more than 209,000 by 24 April.", "sources": [{"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}, {"label": "Citizen Digital: CAP July poll, Babu leads, Kagure gains", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-still-leads-as-agnes-kagure-gains-traction-n387114", "date": "2026-07-25"}, {"label": "Nation: IEBC 1.8m new voters, Nairobi leads, Kiambu 97,557", "url": "https://nation.africa/kenya/news/iebc-hits-75pc-of-mass-listing-targets-with-1-8m-new-voters-5435836", "date": "2026-04-25"}]}, {"title": "Floods, evictions and Dandora cut both ways", "stance": "threat", "body": "Riparian clearances after the March floods ('all encroachers will be moved') and the Dandora clean-up touch 3,000 families up to 8,000 waste pickers in the settlements. Enforcement without visible protection hands Babu the settlements.", "sources": [{"label": "The Star: flood deaths linked to riparian encroachment", "url": "https://www.the-star.co.ke/counties/nairobi/2026-03-12-nairobi-flood-deaths-linked-to-encroaching-of-riparian-land", "date": "2026-03-12"}, {"label": "Capital FM: Dandora clean-up and waste pickers", "url": "https://capitalfm.africa/dandora-cleanup-puts-waste-pickers-at-a-crossroads-as-nairobi-overhauls-garbage-system/", "date": "2026-08-12"}]}]$j$::jsonb, $j$[{"from": 1, "to": 3, "title": "Decide the vehicle and say it plainly", "diary": {"kind": "media", "title": "Statement: the party question"}, "why": "Indecision since August reads as weakness, and ODM's delegates have already said no.", "how": ["Either: contest ODM's primary under the ODM–UDA framework with Oburu and Ruto's backing, said openly.", "Or: run on UDA within the broad-based camp and drop the ODM flirtation entirely.", "Don't let it run past this fortnight."], "where": ["Nairobi"], "measure": "One clear statement; ODM and UDA reactions.", "sources": [{"label": "Kenyans.co.ke: Sakaja hints at ODM move", "url": "https://www.kenyans.co.ke/news/126119-sakaja-hints-possible-odm-move-ahead-2027-nairobi-race", "date": "2026-08-12"}, {"label": "The Standard: ODM delegates reject Sakaja", "url": "https://www.standardmedia.co.ke/article/2001558772/odm-delegates-reject-sakaja-using-the-party-for-gubernatorial-bid", "date": "2026-09-26"}, {"label": "Kenyans.co.ke: ODM MPs tell Sakaja to face primaries", "url": "https://www.kenyans.co.ke/news/126838-odm-mps-tell-sakaja-face-party-primaries-2027-nairobi-governor-seat", "date": "2026-09-06"}]}, {"from": 2, "to": 7, "title": "Make the record visible: one site a day", "diary": {"kind": "visit", "title": "Delivery visit"}, "why": "The record is real but invisible. One concrete place a day turns adjectives into proof.", "how": ["A Dishi na County kitchen at lunch; the Ngong Road flyover; a newly lit street; a finished road in a near-tie seat.", "Every visit carries one number and one before/after photo.", "Start in the near-ties: Dagoretti North, Lang'ata, Westlands, Mathare, Makadara, Embakasi West."], "where": ["Dagoretti North", "Lang'ata", "Westlands", "Mathare", "Makadara", "Embakasi West"], "measure": "Six visits, six posts, local coverage.", "sources": [{"label": "Citizen Digital: Dishi na County boosts attendance", "url": "https://citizen.digital/article/nairobis-dishi-na-county-programme-boosts-school-attendance-and-learning-n376454", "date": "2026-01-26"}, {"label": "The Star: Sh80bn Ruto–Sakaja pact", "url": "https://www.the-star.co.ke/news/2026-02-17-nairobi-set-for-sh80bn-upgrade-in-ruto-sakaja-pact", "date": "2026-02-17"}, {"label": "TV47: the pact five months on", "url": "https://www.tv47.digital/inside-the-ruto-sakaja-pact-five-months-after-the-ksh80-billion-deal-hit-or-miss-157127/", "date": "2026-07-25"}]}, {"from": 3, "to": 8, "title": "Win the MCAs back, ward by ward", "diary": {"kind": "meeting", "title": "MCA ward fund breakfast"}, "why": "Without Raila, the 70-signature impeachment threat is his alone to manage, and MCAs are his ground machine.", "how": ["Publish each ward's development fund and bursary figures.", "Hold three breakfasts of about 30 MCAs each, across party lines.", "Agree on one visible project per ward before the end of the year."], "where": ["Nairobi"], "measure": "MCAs on record backing him; no new impeachment talk.", "sources": [{"label": "Kenyans.co.ke: MCAs drop impeachment after Raila meeting", "url": "https://www.kenyans.co.ke/news/115877-odm-mcas-drop-sakajas-impeachment-motion-after-raila-meeting", "date": "2025-09-02"}, {"label": "Citizen Digital: MCAs suspend impeachment push", "url": "https://citizen.digital/news/nairobi-mcas-suspend-sakaja-impeachment-push-after-ruto-raila-talks-n368956", "date": "2025-09-02"}]}, {"from": 5, "to": 10, "title": "Settlements: protection before enforcement", "diary": {"kind": "visit", "title": "Settlement upgrade site"}, "why": "Riparian clearances and Dandora can lose him the settlements unless people see protection first.", "how": ["Announce the relocation sites and the Gikomba no-displacement pledge in person.", "Show the Sh3.3bn upgrade and the last-mile power in one named settlement.", "Waste pickers: a cooperative and jobs inside the new garbage system."], "where": ["Dandora", "Mathare", "Kibra"], "measure": "Settlement leaders on record; no new eviction flashpoint.", "sources": [{"label": "The Star: flood deaths linked to riparian encroachment", "url": "https://www.the-star.co.ke/counties/nairobi/2026-03-12-nairobi-flood-deaths-linked-to-encroaching-of-riparian-land", "date": "2026-03-12"}, {"label": "Capital FM: Dandora clean-up and waste pickers", "url": "https://capitalfm.africa/dandora-cleanup-puts-waste-pickers-at-a-crossroads-as-nairobi-overhauls-garbage-system/", "date": "2026-08-12"}, {"label": "The Star: Sh80bn Ruto–Sakaja pact", "url": "https://www.the-star.co.ke/news/2026-02-17-nairobi-set-for-sh80bn-upgrade-in-ruto-sakaja-pact", "date": "2026-02-17"}]}, {"from": 8, "to": 14, "title": "Defend the strongholds: Roysambu and Kasarani", "diary": {"kind": "rally", "title": "Roysambu–Kasarani town hall"}, "why": "CAP has Kagure ahead in the seats that won him 2022. These are the votes to win back first.", "how": ["Resident-association town halls on rates, water and approvals.", "Make Kagure's camp an offer if she is squeezed out of the opposition ticket: her supporters have said they would back him.", "Walk the estates with local MCAs."], "where": ["Roysambu", "Kasarani", "Starehe"], "measure": "Volunteers recruited; MCA endorsements.", "sources": [{"label": "Citizen Digital: CAP July poll, Babu leads, Kagure gains", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-still-leads-as-agnes-kagure-gains-traction-n387114", "date": "2026-07-25"}, {"label": "Kenyans.co.ke: Kagure supporters threaten to back Sakaja", "url": "https://www.kenyans.co.ke/news/127932-kagure-supporters-threaten-back-sakaja-over-unfair-opposition-nominations", "date": "2026-10-18"}, {"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}]}, {"from": 10, "to": 14, "title": "Youth: hawker zones and jobs, not motorcades", "diary": {"kind": "media", "title": "Youth town hall (online)"}, "why": "Babu had 62% of 18–24 year-olds in the September 2025 survey, and Nairobi led registration.", "how": ["Livestream a town hall with hawker and boda representatives.", "One pledge: licensed hawking zones with fixed fees, and a city gig-jobs desk."], "where": ["Online", "CBD"], "measure": "Live viewers; sign-ups under 30.", "sources": [{"label": "Kenyans.co.ke: Babu leads, Sakaja's popularity plummets", "url": "https://www.kenyans.co.ke/news/116303-babu-owino-leads-sakajas-popularity-plummets-ahead-nairobi-2027-governor-race-new-poll", "date": "2025-09-17"}, {"label": "Kenyans.co.ke: Sakaja rules out banning hawking", "url": "https://www.kenyans.co.ke/news/126512-sakaja-rules-out-banning-street-hawking-explains-management-plan", "date": "2026-08-26"}, {"label": "Nation: IEBC 1.8m new voters, Nairobi leads, Kiambu 97,557", "url": "https://nation.africa/kenya/news/iebc-hits-75pc-of-mass-listing-targets-with-1-8m-new-voters-5435836", "date": "2026-04-25"}]}]$j$::jsonb, $j$[{"title": "Opposition nominations", "body": "If Kagure is pushed out of the opposition ticket, her vote is in play.", "sources": [{"label": "Kenyans.co.ke: Kagure supporters threaten to back Sakaja", "url": "https://www.kenyans.co.ke/news/127932-kagure-supporters-threaten-back-sakaja-over-unfair-opposition-nominations", "date": "2026-10-18"}]}, {"title": "DCP's Nairobi push", "body": "Gachagua claims most seats; CAP has DCP first. Watch Gakuya's numbers.", "sources": [{"label": "The Standard: Gachagua vows DCP dominance in Nairobi", "url": "https://www.standardmedia.co.ke/politics/article/2001551837/gachagua-vows-dcp-dominance-in-nairobi-in-2027", "date": "2026-07-02"}, {"label": "Citizen Digital: CAP July poll, Babu leads, Kagure gains", "url": "https://citizen.digital/article/nairobi-governor-race-babu-owino-still-leads-as-agnes-kagure-gains-traction-n387114", "date": "2026-07-25"}]}, {"title": "The long rains", "body": "Another flood season will test the riparian promises in public.", "sources": [{"label": "The Star: flood deaths linked to riparian encroachment", "url": "https://www.the-star.co.ke/counties/nairobi/2026-03-12-nairobi-flood-deaths-linked-to-encroaching-of-riparian-land", "date": "2026-03-12"}]}]$j$::jsonb, 'Groundwork'
from public.campaigns where slug = 'sakaja';
insert into public.campaign_briefs (campaign_id, starts_on, ends_on, headline, the_read, moves, watch, written_by)
select id, date '2026-10-21', date '2026-11-03', $h$In Gachagua's home seat, the DCP primary is the election: be in it, or be its alternative$h$, $j$[{"title": "This is Gachagua's own constituency", "stance": "threat", "body": "Gachagua won Mathira in 2017 with 52,757 votes. In 2022 Ruto took 63,715 here to Raila's 9,328. DCP has since become the region's party: 33% to UDA's 9% in Central, and it won Ol Kalou by 35,440 to 5,450. Whoever carries DCP's ticket in Mathira starts as the favourite.", "sources": [{"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}, {"label": "People Daily: Infotrak, DCP most popular party in Mt Kenya", "url": "https://peopledaily.digital/inside-politics/infotrak-gachaguas-dcp-is-the-most-popular-party-in-mt-kenya", "date": null}, {"label": "IEBC: Ol Kalou by-election result", "url": "https://x.com/IEBCKenya/status/2077965009250828683", "date": "2026-07-16"}]}, {"title": "The incumbent is third and sinking", "stance": "opening", "body": "KenyaTrack (October) has Peter Githinji 'Tropical' 35%, Solomon Maina 'Solo' 29%, MP Eric Wamumbi 19% and Anthony Ndagita 8%, with 9% undecided. Wamumbi chose Ruto, urged DCP to concede Ol Kalou before it won by about 30,000, and keeps fighting Gachagua over the family estate. The anti-Wamumbi vote is the majority.", "sources": [{"label": "TV47: KenyaTrack, Githinji 'Tropical' ahead in Mathira", "url": "https://www.tv47.digital/kenyatrack-survey-puts-githinji-tropical-ahead-in-the-mathira-2027-race-165139/", "date": null}, {"label": "People Daily: Wamumbi confirms WhatsApp exchange with Gachagua", "url": "https://peopledaily.digital/inside-politics/ruto-ally-mp-wamumbi-confirms-whatsapp-exchange-with-gachagua-hints-at-more-messages", "date": null}, {"label": "People Daily: Wamumbi asks DCP to concede Ol Kalou", "url": "https://peopledaily.digital/inside-politics/ol-kalou-by-election-mathira-mp-eric-wamumbi-asks-dcp-to-concede-defeat", "date": null}]}, {"title": "Waruru Gikandi is not yet on the board", "stance": "threat", "body": "The October poll doesn't list Waruru Gikandi at all. Gachagua introduced Githinji at Karatina in September 2025, and he is called the DCP front-runner. The first job of the fortnight is name recognition, and the first decision is whether to seek DCP's ticket or to be the clean alternative for voters tired of both camps.", "sources": [{"label": "TV47: KenyaTrack, Githinji 'Tropical' ahead in Mathira", "url": "https://www.tv47.digital/kenyatrack-survey-puts-githinji-tropical-ahead-in-the-mathira-2027-race-165139/", "date": null}, {"label": "Mountain Journal: Gachagua roars in Mathira", "url": "https://themountainjournal.co.ke/2025/09/14/rigathi-gachagua-roars-in-mathira/", "date": "2025-09-14"}, {"label": "Mt Kenya Times: Gachagua and the DCP aspirants", "url": "https://mountkenyatimes.co.ke/gachagua-kicks-out-uda-mole-from-wamunyoro-heads-to-roll-at-dcp-hq/", "date": null}]}, {"title": "DCP's primary will leave casualties", "stance": "opening", "body": "Six or more aspirants want DCP's Mathira ticket, and Nation reports fights over direct tickets across the region. Whoever loses brings a network with them.", "sources": [{"label": "Nation: Gachagua's picks test DCP's fair nominations promise", "url": "https://nation.africa/kenya/news/politics/why-gachagua-s-picks-test-dcp-s-promise-of-fair-nominations--5533268", "date": null}, {"label": "Nation: DCP primaries threaten to split the party", "url": "https://nation.africa/kenya/news/politics/gachagua-puts-coalition-talks-on-hold-as-dcp-primaries-threaten-to-split-party-5630854", "date": null}, {"label": "Mt Kenya Times: Gachagua and the DCP aspirants", "url": "https://mountkenyatimes.co.ke/gachagua-kicks-out-uda-mole-from-wamunyoro-heads-to-roll-at-dcp-hq/", "date": null}]}]$j$::jsonb, $j$[{"from": 1, "to": 3, "title": "Decide: DCP primary or the clean alternative", "diary": null, "why": "In this seat the decision comes first; everything else follows from it.", "how": ["If DCP: register (KSh10,000; half for youth) and court the ward delegates now.", "If not: position as the Mathira voice who is neither Ruto's MP nor a Wamunyoro pick."], "where": ["Karatina"], "measure": "Decision made and recorded.", "sources": [{"label": "Kenyans.co.ke: DCP nomination fees", "url": "https://www.kenyans.co.ke/news/126713-dcp-releases-2027-nomination-fees-mca-mp-governor-aspirants", "date": "2026-09-02"}, {"label": "Nation: Gachagua's picks test DCP's fair nominations promise", "url": "https://nation.africa/kenya/news/politics/why-gachagua-s-picks-test-dcp-s-promise-of-fair-nominations--5533268", "date": null}]}, {"from": 2, "to": 8, "title": "Six wards in six days", "diary": {"kind": "visit", "title": "Ward walk"}, "why": "He isn't in the poll yet. Presence in every ward is the cheapest fix.", "how": ["Karatina Town market day; Konyu, Ruguru, Iriaini, Magutu, Kirimukuyu.", "Coffee and tea: factory payments and the bonus season; dairy prices.", "Collect consented phone numbers at every stop."], "where": ["Karatina Town", "Konyu", "Ruguru", "Iriaini", "Magutu", "Kirimukuyu"], "measure": "1,000 consented contacts; recognition in the next local poll.", "sources": [{"label": "The Star: tea pay and bonuses from Monday", "url": "https://www.the-star.co.ke/news/2026-10-09-tea-farmers-to-access-september-pay-and-bonuses-from-monday", "date": "2026-10-09"}]}, {"from": 6, "to": 12, "title": "Youth: the protest generation", "diary": {"kind": "meeting", "title": "Youth forum, Karatina"}, "why": "Saba Saba's deaths were concentrated in the region, and the young decide margins.", "how": ["A jobs forum at Karatina University.", "Recruit 30 youth volunteers for TikTok and the walk lists."], "where": ["Karatina Town"], "measure": "Volunteers and first-time voters signed up.", "sources": [{"label": "Citizen Digital: Saba Saba toll rises to 38 (KNCHR)", "url": "https://citizen.digital/article/death-toll-from-saba-saba-protests-rises-to-38-knchr-n366153", "date": null}, {"label": "PARS Gen Z poll report", "url": "https://pars.co.ke/wp-content/uploads/2026/06/Gen-Z-Poll-Report-FINAL-23rd-June-2026.pdf", "date": "2026-06-23"}]}, {"from": 10, "to": 14, "title": "Map the primary's losers", "diary": null, "why": "Whichever way DCP's primary goes, someone leaves it with a following.", "how": ["Name the ward chairs behind Solo, Ndagita and the others.", "Quiet one-to-ones; no public attacks."], "where": ["Mathira"], "measure": "Named contacts in each camp.", "sources": [{"label": "TV47: KenyaTrack, Githinji 'Tropical' ahead in Mathira", "url": "https://www.tv47.digital/kenyatrack-survey-puts-githinji-tropical-ahead-in-the-mathira-2027-race-165139/", "date": null}, {"label": "Mt Kenya Times: Gachagua and the DCP aspirants", "url": "https://mountkenyatimes.co.ke/gachagua-kicks-out-uda-mole-from-wamunyoro-heads-to-roll-at-dcp-hq/", "date": null}]}]$j$::jsonb, $j$[{"title": "DCP's nomination calendar", "body": "When and how DCP picks its Mathira candidate.", "sources": [{"label": "Nation: Gachagua's picks test DCP's fair nominations promise", "url": "https://nation.africa/kenya/news/politics/why-gachagua-s-picks-test-dcp-s-promise-of-fair-nominations--5533268", "date": null}]}, {"title": "Gachagua–Wamumbi feud", "body": "The family-estate fight keeps the race personal and energises DCP's base.", "sources": [{"label": "People Daily: Wamumbi confirms WhatsApp exchange with Gachagua", "url": "https://peopledaily.digital/inside-politics/ruto-ally-mp-wamumbi-confirms-whatsapp-exchange-with-gachagua-hints-at-more-messages", "date": null}]}]$j$::jsonb, 'Groundwork'
from public.campaigns where slug = 'mathira';
insert into public.campaign_briefs (campaign_id, starts_on, ends_on, headline, the_read, moves, watch, written_by)
select id, date '2026-10-21', date '2026-11-03', $h$Roysambu votes for the person: be the one who shows up when the bulldozers come$h$, $j$[{"title": "The ward votes for the person, not the party", "stance": "context", "body": "In 2022, independent Sospeter Gathahu won the ward with 6,317 votes while UDA carried the other four wards and the MP seat. In 2017, Peter Warutere won on Jubilee with 11,829 of 23,195 valid votes, and Gathahu was second.", "sources": [{"label": "Team research: Kenya Electoral Strategy Research", "url": null, "date": null}, {"label": "IEBC 2022 results, as loaded in the Elections atlas", "url": null, "date": null}]}, {"title": "Marurui made the sitting MCA a protest hero", "stance": "threat", "body": "On 4–5 May, homes on contested land in Marurui were demolished after a court ruling: Nation counts about 80 permanent and 20 makeshift structures. Buyers say they got no notice. Gathahu was charged over the Northern Bypass blockade that followed. Land and evictions now define the ward.", "sources": [{"label": "The Star: tears and rubble in Marurui", "url": "https://www.the-star.co.ke/news/2026-05-05-tears-rubble-in-marurui-as-bulldozers-flatten-homes", "date": "2026-05-05"}, {"label": "The Standard: Roysambu MCA charged over Marurui protest", "url": "https://www.standardmedia.co.ke/nairobi/article/2001547065/roysambu-mca-charged-over-marurui-demolition-protest", "date": null}]}, {"title": "Young voters and a crowded field above you", "stance": "opening", "body": "IEBC believes young people now make up more than half the register. A skater declared for MP on 12 October on DCP's ticket as '003 Gen Z Power'. The MP field has six or seven names, so the top of the ballot will split. Hillary Kabila is reported to be preparing an MCA bid.", "sources": [{"label": "Capital FM: IEBC targets hard-to-reach youth", "url": "https://www.capitalfm.co.ke/news/2026/05/iebc-targets-marginalized-hard-to-reach-youth-to-fix-voter-register/", "date": null}, {"label": "The Star: skater Kevin Kiarie declares Roysambu bid", "url": "https://www.the-star.co.ke/news/2026-10-12-skater-kevin-kiarie-declares-2027-mp-bid", "date": "2026-10-12"}, {"label": "Capital FM: how Kenya's youth confront money politics", "url": "https://capitalfm.africa/breaking-the-mold-how-kenyas-youth-are-confronting-money-driven-politics/", "date": null}]}]$j$::jsonb, $j$[{"from": 1, "to": 4, "title": "Marurui: a land and title clinic", "diary": {"kind": "meeting", "title": "Land and title clinic, Marurui"}, "why": "Evictions are the ward's defining fear; practical help beats protest.", "how": ["Bring volunteer lawyers and a surveyor: check titles, sale agreements and court status.", "Start a register of buyers at risk, with consent."], "where": ["Marurui"], "measure": "Households helped; sign-ups.", "sources": [{"label": "The Star: tears and rubble in Marurui", "url": "https://www.the-star.co.ke/news/2026-05-05-tears-rubble-in-marurui-as-bulldozers-flatten-homes", "date": "2026-05-05"}]}, {"from": 3, "to": 10, "title": "Court by court: water, lights, drains", "diary": {"kind": "visit", "title": "Court walk with residents' association"}, "why": "Gathahu won with hyper-local service. Match it court by court.", "how": ["Walk with each residents' association; log every broken light, drain and water outage in public.", "Join the estate WhatsApp groups with a weekly fixed-or-not report."], "where": ["Roysambu"], "measure": "Issues logged and fixed; WhatsApp groups joined.", "sources": [{"label": "Team research: Kenya Electoral Strategy Research", "url": null, "date": null}]}, {"from": 7, "to": 14, "title": "Campus and first-time voters", "diary": {"kind": "meeting", "title": "Campus town hall"}, "why": "Young voters are now the register's majority; IEBC's main obstacle is missing IDs.", "how": ["An ID and registration help desk at the campuses.", "A gig-work and tenant-rights town hall."], "where": ["Roysambu"], "measure": "New registrations helped.", "sources": [{"label": "Capital FM: IEBC targets hard-to-reach youth", "url": "https://www.capitalfm.co.ke/news/2026/05/iebc-targets-marginalized-hard-to-reach-youth-to-fix-voter-register/", "date": null}]}]$j$::jsonb, $j$[{"title": "More demolitions", "body": "Any new court order on contested land in the ward.", "sources": [{"label": "The Star: tears and rubble in Marurui", "url": "https://www.the-star.co.ke/news/2026-05-05-tears-rubble-in-marurui-as-bulldozers-flatten-homes", "date": "2026-05-05"}]}]$j$::jsonb, 'Groundwork'
